gcr(){return"\u06cc\u06a9 \u062a\u0635\u0648\u06cc\u0631 \u06a9\u0627\u0645\u0644 \u0645\u0627\u0644\u06cc \u0628\u0647 \u062f\u0633\u062a \u0622\u0648\u0631\u06cc\u062f. \u062f\u0631\u0622\u0645\u062f\u0647\u0627\u060c \u0647\u0632\u06cc\u0646\u0647\u200c\u0647\u0627 \u0648 \u067e\u0631\u062f\u0627\u062e\u062a\u200c\u0647\u0627\u06cc \u0645\u0639\u0644\u0642 \u062e\u0648\u062f \u0631\u0627 \u0641\u0648\u0631\u0627\u064b \u0628\u0628\u06cc\u0646\u06cc\u062f\u060c \u0633\u0648\u062f \u062e\u0627\u0644\u0635 \u062e\u0648\u062f \u0631\u0627 \u0645\u0627\u0647 \u0628\u0647 \u0645\u0627\u0647 \u067e\u06cc\u06af\u06cc\u0631\u06cc \u06a9\u0646\u06cc\u062f \u0648 \u0628\u0647\u062a\u0631\u06cc\u0646 \u0645\u0634\u062a\u0631\u06cc\u0627\u0646 \u062e\u0648\u062f \u0631\u0627 \u06a9\u0634\u0641 \u06a9\u0646\u06cc\u062f."},
gcu(){return"\u062a\u0642\u0648\u06cc\u0645 \u062d\u0631\u0641\u0647\u200c\u0627\u06cc \u0634\u0645\u0627"},
